5	import java.util.Locale;
6	
7	/**
8	 * 冲突字段人工选择：保留当前值（CURRENT）或接受候选值（CANDIDATE）。不允许选择 BASE。
9	 */
10	public enum FieldSelection {
11	    CURRENT,
12	    CANDIDATE;
13	
14	    /**
15	     * 大小写不敏感地解析请求中的选择值；非法值返回 null，由业务层统一报 400。
16	     */
17	    @JsonCreator
18	    public static FieldSelection fromValue(String value) {
19	        if (value == null) {
20	            return null;
