67	    private void createObservation(String id, String requestId) {
68	        observationService.create(new CreateObservationRequest(requestId, id, "站点A", "1.0", "初始备注"));
69	    }
70	
71	    @Test
72	    void concurrentMergesOnDifferentFieldsBothApply() throws Exception {
73	        createObservation("obs-c1", "req-cc0");
74	
75	        // 两个离线端都基于版本 1：一个改地点，一个改备注；互不冲突，应都生效
76	        List<Callable<ObservationService.WriteOutcome>> tasks = List.of(
77	                () -> observationService.merge("obs-c1",
78	                        new MergeObservationRequest("req-cc1", 1, "站点B", "1.0", "初始备注")),
79	                () -> observationService.merge("obs-c1",
80	                        new MergeObservationRequest("req-cc2", 1, "站点A", "1.0", "并发备注")));
81	        List<ObservationService.WriteOutcome> outcomes = runConcurrently(tasks);
82	
83	        assertThat(outcomes).allMatch(outcome -> outcome.status() == 200);
84	        ObservationResponse current = observationService.getCurrent("obs-c1");
85	        // 后到者基于提交时的最新版本重新判定：两边修改都应保留，版本只加两次
86	        assertThat(current.version()).isEqualTo(3);
87	        assertThat(current.location()).isEqualTo("站点B");
88	        assertThat(current.note()).isEqualTo("并发备注");
89	        Integer versionRows = jdbcTemplate.queryForObject(
90	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-c1'", Integer.class);
91	        assertThat(versionRows).isEqualTo(3);
92	    }
93	
94	    @Test
95	    void concurrentMergeAndDeleteNeverResurrectsTombstone() throws Exception {
96	        createObservation("obs-c2", "req-cd0");
97	
98	        List<Callable<String>> tasks = List.of(
99	                () -> {
100	                    try {
101	                        observationService.merge("obs-c2",
102	                                new MergeObservationRequest("req-cd1", 1, "站点B", "2.0", "合并备注"));
103	                        return "merge-ok";
104	                    } catch (ApiException e) {
105	                        return "merge-" + e.status().value();
106	                    }
107	                },
108	                () -> {
109	                    try {
110	                        observationService.delete("obs-c2", new DeleteObservationRequest("req-cd2", 1));
111	                        return "delete-ok";
112	                    } catch (ApiException e) {
113	                        return "delete-" + e.status().value();
114	                    }
115	                });
116	        List<String> results = runConcurrently(tasks);
117	
118	        // 串行化后恰好一个成功：先删则合并 410，先合并则删除 409（版本不匹配）
119	        assertThat(results).containsExactlyInAnyOrder(
120	                results.contains("merge-ok") ? "delete-409" : "merge-410",
121	                results.contains("merge-ok") ? "merge-ok" : "delete-ok");
122	
123	        ObservationResponse current = observationService.getCurrent("obs-c2");
124	        assertThat(current.version()).isEqualTo(2);
125	        if (current.deleted()) {
126	            // 删除先生效：墓碑不得被并发合并复活
127	            assertThat(current.location()).isNull();
128	            ObservationResponse tombstone = observationService.getVersion("obs-c2", 2);
129	            assertThat(tombstone.deleted()).isTrue();
130	        } else {
131	            // 合并先生效：内容为新值，删除因版本不匹配被拒绝
132	            assertThat(current.location()).isEqualTo("站点B");
133	        }
134	        Integer versionRows = jdbcTemplate.queryForObject(
135	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-c2'", Integer.class);
136	        assertThat(versionRows).isEqualTo(2);
137	    }
138	
139	    @Test
140	    void concurrentSameRequestIdReplaysSingleResult() throws Exception {
141	        createObservation("obs-c3", "req-ci0");
142	
143	        // 同一 requestId、相同参数并发提交 4 次：全部返回同一结果，只产生一个新版本
144	        List<Callable<ObservationService.WriteOutcome>> tasks = new ArrayList<>();
145	        for (int i = 0; i < 4; i++) {
146	            tasks.add(() -> observationService.merge("obs-c3",
147	                    new MergeObservationRequest("req-ci1", 1, "站点B", "2.0", "并发重放")));
148	        }
149	        List<ObservationService.WriteOutcome> outcomes = runConcurrently(tasks);
150	
151	        assertThat(outcomes).allMatch(outcome -> outcome.status() == 200);
152	        assertThat(outcomes).allMatch(outcome -> outcome.body().version() == 2);
153	        ObservationResponse current = observationService.getCurrent("obs-c3");
154	        assertThat(current.version()).isEqualTo(2);
155	        assertThat(current.location()).isEqualTo("站点B");
156	        Integer requestRows = jdbcTemplate.queryForObject(
157	                "SELECT COUNT(*) FROM request_log WHERE request_id = 'req-ci1'", Integer.class);
158	        assertThat(requestRows).isEqualTo(1);
159	        Integer versionRows = jdbcTemplate.queryForObject(
160	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-c3'", Integer.class);
161	        assertThat(versionRows).isEqualTo(2);
162	    }
