164	    @Test
165	    void concurrentCreatesOnSameObservationIdYieldSingleRecord() throws Exception {
166	        List<Callable<String>> tasks = new ArrayList<>();
167	        for (int i = 0; i < 3; i++) {
168	            final int index = i;
169	            tasks.add(() -> {
170	                try {
171	                    observationService.create(new CreateObservationRequest(
172	                            "req-ck" + index, "obs-c4", "站点" + index, "1.0", "备注"));
173	                    return "ok";
174	                } catch (ApiException e) {
175	                    return String.valueOf(e.status().value());
176	                }
177	            });
178	        }
179	        List<String> results = runConcurrently(tasks);
180	
181	        assertThat(results).filteredOn("ok"::equals).hasSize(1);
182	        assertThat(results).filteredOn("409"::equals).hasSize(2);
183	        ObservationResponse current = observationService.getCurrent("obs-c4");
184	        assertThat(current.version()).isEqualTo(1);
185	        Integer versionRows = jdbcTemplate.queryForObject(
186	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = 'obs-c4'", Integer.class);
187	        assertThat(versionRows).isEqualTo(1);
