package com.example.starter.observation;

import org.springframework.http.HttpStatus;

import java.util.List;

/**
 * 圆弧三方合并冲突：圆弧集合整体是一个完整字段组，冲突时整组报 409（conflictFields 固定为 ["arcs"]）。
 *
 * <p>该异常在事务上配置为不回滚：抛出前已删除 requestId 占位（失败不占键），
 * 事务提交仅落库“未解决冲突”标记（conflict_pending），供后续裁定引用时判定 422。
 */
public class ArcMergeConflictException extends ApiException {

    public ArcMergeConflictException(String message, int currentVersion) {
        super(HttpStatus.CONFLICT, message, List.of("arcs"), currentVersion);
    }
}

package com.example.starter.observation;

/**
 * 圆弧分量：方位误差区间（圆周区间）的原子字段组，起始角与弧长不可拆分，
 * 三方合并与裁定均按整组处理，绝不把一次提交的起始角与另一次提交的弧长拼组。
 *
 * <p>全部使用整数（千分之一度），禁止浮点：359 度与 1 度相距 2 度而非 358 度。
 *
 * @param startAngle 圆弧起始角，单位千分之一度，取值 0 至 359999
 * @param arcLength  正向弧长，单位千分之一度，取值 1 至 180000；区间含两端，按模 360000 绕回
 */
public record ArcComponent(Integer startAngle, Integer arcLength) {
}

package com.example.starter.observation;

/**
 * 裁定引用：一条圆弧观测记录的当前版本，字段身份（observationId）与源版本（version）不可省。
 *
 * @param observationId 引用的圆弧观测记录唯一标识
 * @param version       引用的源版本号，裁定时必须等于该记录当前版本，否则 409
 */
public record ArcSourceRef(String observationId, Integer version) {
}

package com.example.starter.observation;

import java.util.List;

/**
 * 圆弧观测记录快照：对应 arc_observation_current 当前状态或某历史版本的完整内容。
 *
 * @param observationId   圆弧观测记录唯一标识
 * @param version         版本号，从 1 开始
 * @param deleted         是否为删除墓碑：true 时 arcs 为空
 * @param conflictPending 是否存在未解决冲突：true 时禁止参与裁定，人工裁决后清除
 * @param arcs            该版本全部圆弧分量，按起始角升序；墓碑版本为空列表
 */
public record ArcObservationSnapshot(
        String observationId,
        int version,
        boolean deleted,
        boolean conflictPending,
        List<ArcComponent> arcs) {
}

